/**
 * Places an issue under a parent of its own project, or makes it a root issue
 * again (`parentId: null`). Its sub-issues move with it, so the depth check
 * looks at where its deepest descendant would land.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId !== null) {
    const all = await issueRepo.listAllIssues(input.orgId);
    const byId = indexIssues(all);
    const parent = requireParent(byId, input.parentId, issue.projectId);

    // Walking up from the parent reaches the issue itself exactly when the
    // parent is the issue or sits below it.
    for (
      let cursor: Issue | undefined = parent;
      cursor !== undefined;
      cursor = cursor.parentId === null ? undefined : byId.get(cursor.parentId)
    ) {
      if (cursor.id === issue.id) {
        throw new IssueHierarchyError(issue.id, "cycle");
      }
    }

    const height = heightOf(all, issue.id);
    if (levelOf(byId, parent) + 1 + height > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(issue.id, "too_deep");
    }
  }

  if (issue.parentId === input.parentId) return issue;

  await issueRepo.setIssueParent(input.orgId, issue.id, input.parentId);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    changedFields: ["parentId"],
  });

  return requireFound(
    await issueRepo.findIssueById(input.orgId, issue.id),
    "Issue",
    issue.id,
  );
}

export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listChildIssues(orgId, issueId);
}

export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const below = descendantsOf(await issueRepo.listAllIssues(orgId), issueId)
    .filter((i) => !isArchived(i));
  const closed = below.filter(isClosed).length;
  return { total: below.length, open: below.length - closed, closed };
}

function isClosed(issue: Issue): boolean {
  return CLOSED_ISSUE_STATUSES.includes(issue.status);
}

function indexIssues(all: readonly Issue[]): Map<IssueId, Issue> {
  return new Map(all.map((i) => [i.id, i]));
}

function childrenIndex(all: readonly Issue[]): Map<IssueId, Issue[]> {
  const children = new Map<IssueId, Issue[]>();
  for (const i of all) {
    if (i.parentId === null) continue;
    const list = children.get(i.parentId) ?? [];
    list.push(i);
    children.set(i.parentId, list);
  }
  return children;
}

/** Every issue below `rootId` at any depth, archived ones included. */
function descendantsOf(all: readonly Issue[], rootId: IssueId): Issue[] {
  const children = childrenIndex(all);
  const result: Issue[] = [];
  const seen = new Set<IssueId>([rootId]);
  const queue: IssueId[] = [rootId];
  while (queue.length > 0) {
    const current = queue.shift() as IssueId;
    for (const child of children.get(current) ?? []) {
      if (seen.has(child.id)) continue;
      seen.add(child.id);
      result.push(child);
      queue.push(child.id);
    }
  }
  return result;
}

/** Levels between `rootId` and its deepest descendant (0 for a leaf). */
function heightOf(all: readonly Issue[], rootId: IssueId): number {
  const children = childrenIndex(all);
  const seen = new Set<IssueId>([rootId]);
  let frontier: IssueId[] = [rootId];
  let height = 0;
  for (;;) {
    const next: IssueId[] = [];
    for (const id of frontier) {
      for (const child of children.get(id) ?? []) {
        if (seen.has(child.id)) continue;
        seen.add(child.id);
        next.push(child.id);
      }
    }
    if (next.length === 0) return height;
    height += 1;
    frontier = next;
  }
}

function levelOf(byId: Map<IssueId, Issue>, issue: Issue): number {
  let level = 0;
  const seen = new Set<IssueId>([issue.id]);
  let cursor = issue;
  while (cursor.parentId !== null) {
    const up = byId.get(cursor.parentId);
    if (up === undefined || seen.has(up.id)) break;
    seen.add(up.id);
    level += 1;
    cursor = up;
  }
  return level;
}

/** A parent must be a live issue of the same project and workspace. */
function requireParent(
  byId: Map<IssueId, Issue>,
  parentId: IssueId,
  projectId: Issue["projectId"],
): Issue {
  const parent = byId.get(parentId);
  if (parent === undefined || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/**
 * Called after a sub-issue stopped being open. Tells the direct parent's
 * assignee when nothing open is left anywhere below that parent.
 */
async function announceCompletion(actor: Actor, child: Issue): Promise<void> {
  if (child.parentId === null) return;

  const all = await issueRepo.listAllIssues(child.orgId);
  const parent = all.find((i) => i.id === child.parentId);
  if (parent === undefined || isArchived(parent)) return;
  if (parent.assigneeId === null) return;

  const stillOpen = descendantsOf(all, parent.id).some(
    (i) => !isArchived(i) && !isClosed(i),
  );
  if (stillOpen) return;

  await notify(parent.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues are completed",
    body: `Every sub-issue of issue ${parent.id} is closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}
